fn snapshot_pair_v1(&self,control:&RuntimeControl)->Result<usize,crate::experimental_swift_reactor::control::SnapshotAdmissionErrorV1>{
        use crate::experimental_swift_reactor::control::SnapshotAdmissionErrorV1 as E;
        use crate::experimental_swift_reactor::control::SwiftReservationCategory as C;
        let header=accounted_header_bytes().ok_or(E::Arithmetic)?;
        control.snapshot_ticket_identity_v1(self.header.as_ref().ok_or(E::Layout)?)?;
        for ticket in &self.buffers {control.snapshot_ticket_identity_v1(ticket.as_ref().ok_or(E::Layout)?)?;}
        control.snapshot_ticket_v1(self.header.as_ref().ok_or(E::Layout)?,C::Wasi,header)?;
        let capacities=[self.context.scratch.capacity(),self.context.rollback.capacity(),self.context.stdout.capacity(),self.context.stderr.capacity()];
        let mut total=header;
        for (ticket,bytes) in self.buffers.iter().zip(capacities) {
            control.snapshot_ticket_v1(ticket.as_ref().ok_or(E::Layout)?,C::Wasi,bytes)?;
            total=total.checked_add(bytes).ok_or(E::Arithmetic)?;
        }
        Ok(total)
    }

fn into_parts(self)->(&'a mut Option<super::cache::SwiftFunctionCache>,&'a mut RuntimeControl,Option<&'a AccountedWasi>,AdoptedProof){
        let Self {cache,control,wasi,adopted}=self;
        (cache,control,wasi,adopted)
    }

fn construct_snapshot_owned_v1(owners:super::super::control::SnapshotScopeBorrowV1<'_>,claims:&UnverifiedProfileDigestBytesV1,rows:&mut File,snapshot:&mut File)->SnapshotOuterV1{
    let (cache,control,wasi,adopted)=owners.into_parts();
    construct_profile_core_v1(cache,control,wasi,adopted,&selected_initial_profile_v1(),claims,rows,SnapshotBranchV1{output:snapshot})
}

fn complete<T>(
        self,
        returned_phase_storage: T,
        outcome: &mut Option<SwiftRunFailure>,
    ) {
        let (control, wasi, header) = drop_cleanup_return_storage(self, returned_phase_storage);
        if let Some(ticket) = header {
            let _ = control.drop_reserved_with_wasi((), ticket, wasi.map(AccountedWasi::usage));
        }
        *outcome = control.record_cleanup(wasi.map(AccountedWasi::usage));
    }

fn drop_cleanup_return_storage<'a, T>(
    tail: CacheCleanupTail<'a>,
    storage: T,
) -> CleanupCompletionParts<'a> {
    let CacheCleanupTail {
        control,
        wasi,
        header,
        failure,
    } = tail;
    drop((storage, failure));
    (control, wasi, header)
}

